-- L18-l1-otakudle-genres.rollback.sql (lane magazine, round 2, run O1; generated by docs/anime/data/dle/gen-l18.mjs, do not edit by hand)
--
-- What:   undoes L18: the view of 023 (Demographic) back, the seven old columns of the game otakudle in their old order (series, gender, species, role, demographic, year, studio), the old species values
--         (and the Wikipedia row of Natsu Dragneel), the old spelling "Weekly Shonen Jump" of Demon Slayer, Jujutsu Kaisen and Naruto, the entity_sources rows of L18, then the two columns of series_facts dropped.
--         series_facts.demographic was never touched. Apply at a day boundary like L18 (same remark on guesses). Idempotent.
-- o1-transaction: single, ONE DO block (atomic on its own, in psql and in the Supabase SQL Editor).

do $o1l18r$
begin
perform set_config('lock_timeout', '5s', true);
perform set_config('client_min_messages', 'warning', true);


-- The view first: the columns it reads are dropped last.
create or replace view public.dle_src_anime_character with (security_invoker = true) as
with first_studio as (
  select s.group_id,
    coalesce(
      nullif(array(
        select distinct case when e ->> 'name' = 'Studio Pierrot' then 'Pierrot' else e ->> 'name' end
        from jsonb_array_elements(s.studios) as e
        where (e -> 'seasons') @> '[1]'::jsonb
      ), '{}'),
      nullif(array(
        select distinct case when e ->> 'name' = 'Studio Pierrot' then 'Pierrot' else e ->> 'name' end
        from jsonb_array_elements(s.studios) as e
        where coalesce(jsonb_array_length(case when jsonb_typeof(e -> 'seasons') = 'array' then e -> 'seasons' end), 0) = 0
      ), '{}')
    ) as studios
  from public.series s
), pool as (
  select c.id, c.name, c.name_native, c.aliases, c.slug,
    f.gender, f.species, f.role_at_debut, f.first_appearance, f.voice_actor_ja, f.featured,
    g.slug as series_slug, s.title_en, s.aliases as series_aliases, sf.demographic,
    nullif(btrim(to_jsonb(s) ->> 'franchise'), '') as franchise,
    case when s.type = 'anime_original' then s.anime_start_year else s.manga_start_year end as work_year,
    fs.studios
  from public.characters c
  join public.character_facts f on f.character_id = c.id
  join public.series s on s.group_id = c.group_id and s.published
  join public.groups g on g.id = c.group_id and g.site_id = 'anime'
  join first_studio fs on fs.group_id = s.group_id
  left join public.series_facts sf on sf.group_id = s.group_id
  where c.status = 'published'
)
select
  p.id::text as entity_id,
  p.name,
  array(select distinct n from unnest(array[p.name, p.name_native, p.title_en] || p.aliases || p.series_aliases) as n where nullif(btrim(n), '') is not null) as search,
  jsonb_build_object(
    'series', jsonb_build_object('v', p.title_en, 'p', case when p.franchise is not null then jsonb_build_array(p.franchise) end),
    'gender', jsonb_build_object('v', p.gender),
    'species', jsonb_build_object('v', p.species),
    'role', jsonb_build_object('v', p.role_at_debut),
    'demographic', jsonb_build_object('v', p.demographic),
    'year', jsonb_build_object('v', p.work_year),
    'studio', jsonb_build_object('v', to_jsonb(p.studios))
  ) as attrs,
  jsonb_strip_nulls(jsonb_build_object('voice_actor_ja', p.voice_actor_ja, 'initial', upper(left(p.name, 1)))) as hints,
  (select ei.thumb_path from public.entity_images ei
    where ei.site_id = 'anime' and ei.kind = 'character' and ei.slug = p.series_slug || '/' || p.slug and ei.license_verified and ei.thumb_path is not null) as thumb_path,
  p.series_slug as balance_key,
  p.featured and p.voice_actor_ja is not null as can_be_target
from pool p;

revoke all on table public.dle_src_anime_character from public, anon, authenticated;
grant select on table public.dle_src_anime_character to service_role;

begin
  if exists (select 1 from public.dle_games where id = 'otakudle') and exists (select 1 from public.dle_attributes where game_id = 'otakudle' and key = 'genres') then
    delete from public.dle_attributes where game_id = 'otakudle' and key = 'genres';
    update public.dle_attributes set position = case key when 'gender' then 8 when 'species' then 9 when 'role' then 10 when 'year' then 11 when 'studio' then 12 end
      where game_id = 'otakudle' and key in ('gender', 'species', 'role', 'year', 'studio');
    insert into public.dle_attributes (game_id, key, kind, position, near) values ('otakudle', 'demographic', 'single', 5, null);
    update public.dle_attributes set position = case key when 'gender' then 2 when 'species' then 3 when 'role' then 4 when 'year' then 6 when 'studio' then 7 end
      where game_id = 'otakudle' and key in ('gender', 'species', 'role', 'year', 'studio');
  end if;
end;

with f(series, character, old_value, new_value) as (values
    ('dragon-ball', 'captain-ginyu', 'ginyu-race-mutant', 'ginyu-s-race-mutant'),
    ('dragon-ball', 'babidi', 'bibidi-race', 'bibidi-s-race'),
    ('dragon-ball', 'zarbon', 'zarbon-race', 'zarbon-s-race'),
    ('dragon-ball', 'dodoria', 'dodoria-race', 'dodoria-s-race'),
    ('dragon-ball', 'recoome', 'recoome-race', 'recoome-s-race'),
    ('dragon-ball', 'jiren', 'jiren-race', 'jiren-s-race'),
    ('fairy-tail', 'natsu-dragneel', 'human', 'demon'),
    ('fullmetal-alchemist', 'father', 'homunculus', 'homunculu'),
    ('fullmetal-alchemist', 'king-bradley', 'homunculus', 'homunculu'),
    ('inuyasha', 'sesshomaru', 'dog-daiyokai', 'dog-daiy-kai'),
    ('inuyasha', 'naraku', 'spider-hanyo', 'spider-hany-spider-y-kai-spirit'),
    ('inuyasha', 'kagura', 'wind-yokai', 'wind-y-kai'),
    ('inuyasha', 'kanna', 'nothing-yokai', 'nothing-y-kai'),
    ('inuyasha', 'jaken', 'imp-yokai', 'imp-y-kai'),
    ('tower-of-god', 'evan-edrok', 'silver-dwarves', 'silver-dwarve'),
    ('tower-of-god', 'hwa-ryun', 'red-witches', 'red-witche')
)
update public.character_facts cf set species = f.new_value
from f
join public.groups g on g.site_id = 'anime' and g.slug = f.series
join public.characters c on c.group_id = g.id and c.slug = f.character
where cf.character_id = c.id and cf.species = f.old_value;

insert into public.entity_sources (entity_type, entity_id, field, source, source_ref, source_url, fetched_at)
select 'character', 'natsu-dragneel', 'species', 'wikipedia', null, 'https://en.wikipedia.org/wiki/Natsu_Dragneel', '2026-11-02T00:00:00Z'::timestamptz
where exists (select 1 from public.characters c join public.groups g on g.id = c.group_id where g.site_id = 'anime' and g.slug = 'fairy-tail' and c.slug = 'natsu-dragneel')
on conflict (entity_type, entity_id, field, source) do nothing;

update public.series s set magazine = 'Weekly Shonen Jump'
from public.groups g
where g.id = s.group_id and g.site_id = 'anime' and g.slug in ('demon-slayer', 'jujutsu-kaisen', 'naruto') and s.magazine = 'Weekly Shōnen Jump';

delete from public.entity_sources where entity_type = 'series' and field in ('otakudle.genres', 'otakudle.year');

alter table public.series_facts drop column if exists genres, drop column if exists work_year;

begin
  if exists (select 1 from public.dle_entities where game_id = 'otakudle') then
    perform public.dle_refresh_entities('otakudle');
  end if;
end;

notify pgrst, 'reload schema';

end $o1l18r$;
